/usr/bin/bash -lc "mkdir -p final_answer
perl - <<'PERL'
use strict;
use warnings;

my "'$table = '"'/tmp/asv_table.tsv';
my "'$fasta = '"'/tmp/asv_rep.fasta';
my "'$out = '"'final_answer/asv_abundance.tsv';
my @want = qw(
  mFMT_cecal_1191_2 mFMT_cecal_1191_3 mFMT_cecal_1275_1 mFMT_cecal_1275_2
  mFMT_cecal_1275_4 hFMT_cecal_1296_1 hFMT_cecal_1296_2 hFMT_cecal_1296_3
  hFMT_cecal_1297_1 hFMT_cecal_1297_2 hFMT_cecal_1297_4 noFMT_cecal_1192_1
  noFMT_cecal_1192_3 noFMT_cecal_1294_1 noFMT_cecal_1294_2 noFMT_cecal_1294_3
  noFMT_cecal_1295_4
);

my %seq;
open my "'$ff, '"'<', "'$fasta or die "$fasta: $!";
my ($id, $s) = (undef, '"'');
while (my "'$line = <$ff>) {
    chomp $line;
    if ($line =~ /''^>('"\\S+)/) {
        if (defined "'$id) { die "duplicate FASTA ID $id'"\\n\" if exists "'$seq{$id}; $seq{$id} = uc $s; }
        ($id, $s) = ($1, '"'');
    } else {
        "'$line =~ s/'"\\s+//g;
        "'$s .= $line;
    }
}
if (defined $id) { die "duplicate FASTA ID $id'"\\n\" if exists "'$seq{$id}; $seq{$id} = uc $s; }
close $ff;

open my $tf, '"'<', "'$table or die "$table: $!";
my (@hdr, %col, @rows);
while (my $line = <$tf>) {
    chomp $line;
    next if $line =~ /''^# Constructed/;
    if (!@hdr) {
        die "missing table header'"\\n\" unless "'$line =~ /''^#OTU ID'"\\t/;
        @hdr = split /\\t/, "'$line, -1;
        for my $i (1 .. $#hdr) { die "duplicate sample column $hdr[$i]'"\\n\" if exists "'$col{$hdr[$i]}; $col{$hdr[$i]} = $i; }
        next;
    }
    next if $line eq '"'';
    my @v = split /\\t/, "'$line, -1;
    die "wrong field count for $v[0]: ".scalar(@v)." vs ".scalar(@hdr)."'"\\n\" unless @v == @hdr;
    my %counts;
    for my "'$sample (@want) {
        die "missing required sample $sample in Galaxy table'"\\n\" unless exists "'$col{$sample};
        my $x = $v[$col{$sample}];
        die "non-numeric count for $v[0]/$sample: $x'"\\n\" unless "'$x =~ /''^'"\\d+(?:\\.\\d+)?"'$/;
        die "fractional count for $v[0]/$sample: $x'"\\n\" unless "'$x == int($x);
        $counts{$sample} = int($x);
    }
    push @rows, [$v[0], '"\\%counts];
}
close "'$tf;

my %seen_seq;
for my $row (@rows) {
    my ($fid, $counts) = @$row;
    die "feature $fid has no representative sequence'"\\n\" unless exists "'$seq{$fid};
    die "invalid sequence for $fid'"\\n\" unless "'$seq{$fid} =~ /''^[ACGT]+$/;
    die "duplicate ASV sequence for $fid and $seen_seq{$seq{$fid}}'"\\n\" if exists "'$seen_seq{$seq{$fid}};
    $seen_seq{$seq{$fid}} = $fid;
}
for my $fid (keys %seq) { die "representative sequence $fid absent from table'"\\n\" unless grep { "'$_->[0] eq $fid } @rows; }

open my $of, '"'>', "'$out or die "$out: $!";
print {$of} join("'"\\t\", 'sequence', @want), \"\\n\";
for my "'$row (@rows) {
    my ($fid, $counts) = @$row;
    print {$of} join("'"\\t\", "'$seq{$fid}, map { $counts->{$_} } @want), "'"\\n\";
}
close "'$of;

my %want = map { $_ => 1 } @want;
my $total = 0;
for my $row (@rows) { $total += $_ for values %{$row->[1]}; }
print "wrote=$out'"\\nASVs=\", scalar(@rows), \" FASTA_records=\", scalar(keys %seq), \" samples=\", scalar(@want), \" total_count="'$total'"\\n\";
print \"header=\", join(',', @want), \"\\n\";
PERL
wc -l final_answer/asv_abundance.tsv
sed -n '1,5p' final_answer/asv_abundance.tsv"

