wc -l final_answer/asv_abundance.tsv
sed -n '1,5p' final_answer/asv_abundance.tsv"

/usr/bin/bash -lc "set -e
awk -F '\\t' '
NR==1 { if ("'$1!="sequence") exit 1; nf=NF; next }
NF!=nf { print "bad field count line",NR,NF,nf; bad=1 }
$1 !~ /''^[ACGT]+$/ { print "bad sequence line",NR; bad=1 }
{ if (seen[$1]++) { print "duplicate sequence line",NR; bad=1 } for (i=2;i<=NF;i++) { if ($i !~ /''^[0-9]+$/) { print "bad count line",NR,"field",i,$i; bad=1 } sum[i]+=$i } }
END { if (NR!=321) { print "unexpected lines",NR; bad=1 } if (nf!=18) { print "unexpected columns",nf; bad=1 } if (bad) exit 1; print "validated lines="NR,"asvs="NR-1,"columns="nf-1; for(i=2;i<=nf;i++) print $(i) > "/dev/stderr"; }
'"' final_answer/asv_abundance.tsv
printf '%s\\n' '--- per-sample totals ---'
awk -F '\\t' 'NR==1{for(i=2;i<=NF;i++) h[i]="'$i; next} {for(i=2;i<=NF;i++) s[i]+=$i} END{for(i=2;i<=NF;i++) print h[i]"'"\\t\"s[i]}' final_answer/asv_abundance.tsv
printf '%s\\n' '--- sequence lengths ---'
awk -F '\\t' 'NR>1{l=length("'$1); c[l]++} END{for (x in c) print x,c[x]}'"' final_answer/asv_abundance.tsv | sort -n
printf '%s\\n' '--- final_answer files ---'
find final_answer -maxdepth 1 -type f -printf '%f\\n' | sort"

